struct kexec_segment {
    unsigned long buf, buflen;
    unsigned long mem, memlen;
};

// Prepare segments (kernel loaded into memory at 0x100000)
struct kexec_segment segments[1] = {
    {
        (unsigned long)0x100000, 1024 * 1024, // Source
        (unsigned long)0x2000000, 1024 * 1024  // Destination
    }
};

// Load kernel image
long res = kexec_load(
    0x2000000,  // entry physical address
    1,          // nr_segments
    segments,
    0x1         // KEXEC_LOAD_ON_CRASH
);

